    progAbacusA2Part2: ".",
    progAbacusQ3: "How much daily practice is expected at home?",
    progAbacusA3: "We recommend 10 to 15 minutes of regular daily practice rather than marathon weekend sessions. Consistency helps children turn conscious bead calculations into subconscious visualization.",
    progAbacusQ4: "Are the trainers certified?",
    progAbacusA4: "Yes. Classes are conducted under the leadership of Founder Neha Patil, who is a Certified Trainer of Abacus & Vedic Mathematics (MCA, Authorised Skill Centre in Abacus Reg. CI2023/100000455).",
