    progVedicQ1: "Will school teachers deduct marks for using Vedic shortcuts?",
    progVedicA1: "No. In subjective school exams (CBSE/ICSE), students write out all standard curriculum steps for full method marks. They use Vedic Maths to calculate answers rapidly and verify their accuracy, saving time and preventing calculation errors.",
