    // FAQs Page
    faqBadge: "CLEAR ANSWERS",
    faqTitle: "Frequently Asked Queries",
    faqSubtitle: "Answering Your Mathematical Doubts",
    faqDesc: "Need clarity on visual abacus lessons, fees, batches, or study structures? Read our verified answers.",
    faqCategoryAll: "All",
    faqCategoryGeneral: "General",
    faqCategoryAbacus: "Abacus Math",
    faqCategoryVedic: "Vedic Maths",
    faqCategorySchool: "School Maths",
    faq1Question: "What is the ideal age to enroll my child in Abacus classes?",
    faq1Answer: "The ideal age window for starting visual abacus matches physical brain growth ratios: between 4 and 14 years old (with peak results between 5 and 9 years). During this stage, a child's brain structure is highly active and elastic, meaning they rapidly map numerical bead visuals into their subconscious spatial storage.",
    faq2Question: "What is the difference between Abacus and Vedic Mathematics?",
    faq2Answer: "Abacus focuses on tactile bead sliding for young kids (ages 4-14) to develop spatial memory. Vedic Maths uses 16 mathematical sutras for older kids (ages 10+) to compute squares, roots, and algebra 10-15x faster without visual aids.",
    faq3Question: "Are the instructors at Arnav Abacus Academy certified?",
    faq3Answer: "Yes, 100%! Arnav Abacus Academy operates under direct faculty leadership. Founder Neha Patil is a fully IIVA (Indian Institute of Vedic Maths & Abacus) Certified Professional.",
    faq4Question: "How long is each segment session, and what are the class schedules?",
    faq4Answer: "We are open seven days a week to accommodate busy schedules, offering flexible rolling sessions on both weekdays and weekends.",
    faq5Question: "Will learning the visual abacus confuse my child's school math syllabus?",
    faq5Answer: "No, on the contrary! Abacus training does not conflict with CBSE, ICSE, or State syllabus counting. Rather, it supercharges the underlying calculative speed.",

    // Showcase
    showcaseTitle: "Transformation, Excellence & Success",
    showcaseSubtitle: "Witness the real, verified milestones of Arnav Abacus Academy. From securing 1st Ranks at International Abacus Competitions under Dr. Kiran Bedi's honors to receiving prestigious National & community entrepreneurship awards at IIT Delhi.",
