    showcaseBottomTitle: "Let Your Child Be Our Next Success Story!",
    showcaseBottomSubtitle: "Every child has the innate power to calculate at photographic speeds. Give them a complimentary learning assessment.",
    showcaseItem1Title: "1st Rank at International Abacus Competition",
    showcaseItem1Text: "Arnav Patil, the brilliant young brand ambassador of Arnav Abacus Academy, achieved the ultimate glory by securing 1st Rank at the International Abacus Competition on National Mathematics Day 2025. The champion's trophy and certificate were proudly presented by India's iconic former IPS officer and Lt. Governor, Dr. Kiran Bedi, alongside the CEO of IIVA.",
    showcaseItem2Title: "Back-to-Back International Champion: Arnav Patil",
    showcaseItem2Text: "Within just one week, Arnav Abacus Academy’s brand ambassador, Arnav Patil, has clinched yet another 1st Rank at the International level (C1 Category - Advanced Level) at the 8th International Abacus Competition 2025 in Pune. Razor-sharp accuracy meets relentless consistency!",
    showcaseItem3Title: "Business Excellence Award 2025",
    showcaseItem3Text: "Arnav Abacus Academy Founder & Director, Neha Patil, was honored with the prestigious Business Excellence Award at the 8th International Abacus Competition 2025. Presented by Mr. Sanjay Kalamkar, CEO of Smart Kid Abacus Learning Pvt Ltd, this accolade celebrates her exceptional leadership.",
    showcaseItem4Title: "Women’s Achiever Award & Community Recognition",
    showcaseItem4Text: "Hattrick alert! 🏆 Founder & Director, Neha Patil, marks a remarkable three-award milestone in just one month! Honored with the prestigious Women’s Achiever Award by the Leva Patidar Bhatru Mandal Wakad (LPBMW), this special tribute celebrates her dual dedication—driving digital excellence at Wisdom World School and fostering mental arithmetic mastery at Arnav Abacus Academy.",
    showcaseItem5Title: "Best Student of the Year (2025-26)",
    showcaseItem5Text: "Meet our silent performer and supersonic star, Spriha Kamath—crowned Best Student of the Year! Spriha’s journey is defined by stellar consistency, absolute discipline, timely homework, and flawless math visualization skills.",
    showcaseItem6Title: "3rd Rank at International Abacus Competition",
    showcaseItem6Text: "Huge congratulations to our brilliant high-performer, Hitanshi Agarwal, for securing Rank 3 at the 8th International Abacus Competition 2025 in Pune! Presented by Smart Kid Abacus Learning Pvt Ltd.",
    showcaseItem7Title: "1st Rank at B1 Level International Abacus Competition",
    showcaseItem7Text: "A massive congratulations to our stellar math champion, Shreshth Gupta, for clinching 1st Rank (B1 Level) at the 8th International Abacus Competition 2025 in Pune! Presented by Smart Kid Abacus Learning Pvt Ltd.",
    showcaseItem8Title: "Runner-Up Trophies for Our Seven Stars",
    showcaseItem8Text: "We are thrilled to celebrate our seven rising stars—ranging from Jr. KG to Advanced Levels—who bagged Runner-Up Trophies at the 8th International Abacus Competition 2025 in Pune. Huge congratulations to Prathamesh Zope, Atharva Titave, Hridhaan Bagla, Kriyansh Chhabria, Agastya Patil, Hitansh Agarwal, and Aarav Patil.",
    showcaseItem9Title: "Glimpses of Glory: Competition Highlights (2023-2025)",
    showcaseItem9Text: "Take a look at these proud highlights from our active participation and stellar achievements across State, National, and International Abacus Competitions from 2023 to 2025. A heartfelt thank you to our passionate, supportive parents!",
    showcaseItem10Title: "Abacus Excellence Camp at Bliss International (Summer 2024)",
    showcaseItem10Text: "During our Summer Camp 2024, Arnav Abacus Academy Founder & Director, Neha Patil, mentored brilliant young minds from Bliss International School in the art of Soroban abacus visualization. Watch their learning breakthroughs and video testimonials!",
    showcaseItem11Title: "National Entrepreneurship Excellence Award at IIT Delhi",
    showcaseItem11Text: "Neha Patil receives the prestigious Entrepreneurship Excellence Award from IIVA & IVAS at IIT Delhi on National Mathematics Day. Handed over by the CEO and CMD of IIVA & IVAS, this national accolade celebrates her transformative impact on 150+ students.",
    showcaseItem12Title: "⚡ Unlocked: The \"Perfect 100\" Achievement! Meet Devaansh! ⚡",
    showcaseItem12Text: "Devaansh Ganjoo rewrote the rulebook with a perfect 100/100 in Abacus Runner Level 1 at 2.2x speed and excellent handwriting! Driven by laser focus and a heart of gold, he shines in class. We also honor his super support squad—Happy Father's Day to his dad and Happy Birthday to his mom! Next stop: National & International stages! 🏆",
    showcaseItem13Title: "Champion & Birthday Boy: Meet Sushmit!",
    showcaseItem13Text: "Happy Birthday, Sushmit! 🎂 We celebrate our birthday boy’s recent triumph: scoring a PERFECT 100/100 in Abacus Sr. KG and winning the Championship Trophy! Structured and curious, Sushmit stands out for his proactive habits and excellent handwriting. Heartfelt thanks to Supermom Manisha and Teacher Neha. Our future International Math Champion is destined for greatness! 🏆",
    showcaseItem14Title: "1st Rank State Mental Math Gold Medalist: Anaya Pagar",
    showcaseItem14Text: "Huge congratulations to our brilliant student Anaya Pagar for securing 1st Rank Gold Medal at the State Mental Math Championship! Anaya solved 100 speed math problems in 5 minutes flat with 100% accuracy under the guidance of Founder Neha Patil at Arnav Abacus Academy.",

