    // Interactive Booth
    boothBadge: "Interactive Consultation",
    boothTitle: "The 'Big 5' Math Hurdles",
    boothSubtitle: "Do you agree with these parent concerns ? Arnav Abacus Academy turns math fear into focus and mental speed using whole-brain diagnostics.",
    boothLeftHeader: "Diagnose Goal or Challenge",
    boothTabScience: "Brain Science Behind It",
    boothTabAcademy: "Arnav Academy Way",
    boothAbacusSolutionHeader: "Abacus Math Solution Mapping",
    boothScienceHeader: "The Cognitive Brain Science",
    boothAcademyHeader: "Arnav Academy Engagement Framework",
    boothViewDetails: "View Science & Framework Details",
    boothHideDetails: "Hide Scientific Details",
    boothExploreCta: "Explore Solutions & Diagnostics",
    boothCloseCta: "Hide Solutions",
    concern1Title: "Math Fear & Test Panic",
    concern1Quote: "He gets anxious in math exams and loses confidence completely.",
    c1Sub1: "Whenever Aarav sees large numbers or time limits, he freezes up and starts panicking.",
    c1Sub2: "He says, 'Mom, I just can't do this.' Exam anxiety makes him leave papers incomplete.",
    c1Sub3: "Math anxiety stems from left-brain abstract overload. Visual Abacus maps numbers into tactile spaces.",
    c1Sub4: "By treating calculations as sliding physical beads, the child replaces panic with reflex memory.",
    c1Solution: "Tactile bead-sliding turns abstract numerical symbols into friendly spatial visual patterns, bypassing exam fear.",
    c1Science: "Abacus stimulates the sensory-motor cortex and visual cortex in the right hemisphere. Instead of abstract numbers, children see and move concrete images, which reduces prefrontal stress and prevents test panic.",
    c1Academy: "We use low-stress, game-oriented learning modules, starting with simple confidence sprints. Our regular mock reviews are designed as celebratory milestone events rather than high-pressure tests.",
    concern2Title: "Silly Mistakes & Lack of Concentration",
    concern2Quote: "He knows the steps but makes silly addition errors and loses marks.",
    c2Sub1: "Rohan completes complex problems but slips on simple steps like 7 + 8 = 13.",
    c2Sub2: "It's so frustrating because he understands the logic, but lacks visual focus.",
    c2Sub3: "Silly mistakes occur when focus drifts during repetitive mechanical calculation.",
    c2Sub4: "Abacus demands simultaneous listening, looking, and coordinate movement to enforce absolute focus.",
    c2Solution: "Physical movement of abacus beads engages multiple senses at once, training absolute focus to eliminate calculation slips.",
    c2Science: "Simultaneous motor, visual, and tactile triggers activate cerebellar networks. This coordinates executive control networks in the brain, improving focus span and dramatically reducing calculation errors.",
    c2Academy: "We implement 1-to-8 personal batch ratios where mentors watch each child's speed writing habits. Our custom Speed Writing worksheets enforce digit neatness to eliminate visual errors.",
    concern3Title: "Slow Calculations & Exam Lag",
    concern3Quote: "She takes too long to solve simple calculations, leaving questions unattempted.",
    c3Sub1: "She counts on her fingers slowly and struggles to finish school papers on time.",
    c3Sub2: "Even basic homework sheets take her over an hour to complete.",
    c3Sub3: "Slow calculations occur due to serial verbal counting. Abacus visual memory allows parallel processing.",
    c3Sub4: "Through mental abacus visualization, kids process multiple digits instantly like a camera flash.",
    c3Solution: "Mental abacus visualization replaces slow finger counting with parallel spatial arithmetic, boosting speeds up to 10x.",
    c3Science: "Visualization shifts numeric processing to the visuospatial sketchpad of the working memory. The brain accesses numbers as visual configurations, which allows calculations to occur at the speed of thought.",
    c3Academy: "We run daily high-velocity digital simulations in the classroom. Kids love our speed challenges, converting dull practice into a thrilling, gamified classroom sprint.",
    concern4Title: "Easily Distracted & Can't Sit Still",
    concern4Quote: "He cannot concentrate for more than 5 minutes and leaves assignments half-done.",
    c4Sub1: "Karan gets distracted by the slightest noise. Sitting down for homework is a daily battle.",
    c4Sub2: "His attention span is very short, and he constantly loses track of what he is doing.",
    c4Sub3: "Attention span can be trained. Simultaneous audio dictation and bead sliding pull the child's complete focus.",
    c4Sub4: "By engaging the visual, auditory, and kinesthetic tracks together, we lock the mind in high focus.",
    c4Solution: "Interactive multi-sensory (listen-see-do) dictation loops hold the child's attention fully, expanding focus endurance.",
    c4Science: "Active audio-dictation abacus drills force the brain to block out external auditory distractors, strengthening sensory gating mechanisms and executive attention filters in the prefrontal cortex.",
    c4Academy: "Classes are designed in short, high-energy 10-minute sprints. Instructors keep students continuously engaged with abacus runner levels, keeping them highly focused and excited.",
    concern5Title: "No Concept of Number Logic",
    concern5Quote: "He memorizes math formulas blindly but fails to understand basic logic.",
    c5Sub1: "If I change a single step in a word problem, Kabir gets completely lost.",
    c5Sub2: "He treats math as a list of rules to memorize instead of logical relationships.",
    c5Sub3: "Rote learning fails because formulas are abstract. Abacus models numbers as physical spaces.",
    c5Sub4: "When kids see that a bead means space and quantity, they master true logical relationships.",
    c5Solution: "Visualizes numbers as physical scales, volumes, and spaces, building true logical reasoning rather than blind rote memorization.",
    c5Science: "Abacus builds a cognitive grid mapping numerical magnitude. This engages the parietal lobe's intraparietal sulcus (IPS), which handles spatial mathematical reasoning and true logical number sense.",
    c5Academy: "We teach numerical structures through our Comparison & Synergy Matrix. We blend school syllabus counting with abacus bead properties so kids understand the 'why' behind every math rule.",

