    faq6Question: "Do you provide customized coaching for class 1-10 school exams?",
    faq6Answer: "Yes. Our School Maths curriculum is designed to boost academic confidence and test performance. We analyze each child's active textbook series (NCERT, CBSE, local boards), resolve individual homework blocks, and practice extensive sample question sheets in a calm environment.",
    faq7Question: "Do you offer online sessions or only offline batches?",
    faq7Answer: "Our primary expertise is in premium hand-guided offline batches at our bungalow center, opposite Creative Cameo, ensuring child focus, personal tutor safety, and visual bead engagement. For specialized cases or advanced Vedic math segments, online batches are coordinated on request of the parent.",
    faq8Question: "How do your courses align with the National Education Policy (NEP) 2020?",
    faq8Answer: "Arnav Abacus Academy is fully aligned with the NEP 2020 guidelines. Our Abacus curriculum directly supports Foundational Literacy & Numeracy (FLN) for early ages (3–8 years) through hands-on, experiential learning. Additionally, our Vedic Mathematics classes promote Indian Knowledge Systems (IKS), helping older students build logical reasoning, mental agility, and calculation speed while eliminating mathematics anxiety.",
    faqSyllabusConflictQuestion: "Does the left-to-right Abacus method conflict with the school's right-to-left calculation?",
    faqSyllabusConflictAnswer: "No. Much like bilingual children speak two languages fluently without mixing them, students easily segment school column addition (units first) and mental Abacus visualization (estimating left-to-right). This actually cross-verifies their answers.",
    faqStepMarksQuestion: "How does my child write step-by-step proofs in school math exams if they calculate mentally?",
    faqStepMarksAnswer: "Arnav Abacus Academy trains children to use mental calculations to find answers rapidly, while standard classes teach them how to write down standard proofs. They gain speed in checking their work, saving valuable time during school exams.",
    faqWordProblemsQuestion: "Does Abacus only help with speed calculation, or does it improve word problems and logical reasoning?",
    faqWordProblemsAnswer: "Visualizing numbers on the Abacus grid engages the parietal lobe, which is responsible for spatial reasoning. This spatial mapping directly translates to better understanding of geometric relationships, algebraic logic, and structured word problem solving.",
    faqDoubtsBadge: "Still have unanswered doubts?",
    faqDoubtsTitle: "Direct WhatsApp consultation with Neha Ma'am",
    faqDoubtsDesc: "Connect and directly ask Neha Ma’am about customized kid levels, batch fee scales, custom timetables, and our classroom setup.",
