    pillar2Title: "वर्किंग मेमोरी (कार्यशील स्मृति)",
    pillar2Desc: "अगले अंकों को संसाधित करते समय मध्यवर्ती गणनाओं को मन में संजोए रखना, जिससे अल्पकालिक स्मृति क्षमता का विस्तार होता है।",
    pillar2Obs: "तेज बहु-पंक्ति जोड़ के दौरान देखा जाता है जहां पहले के उप-योग बिना लिखे याद रखे जाते हैं।",

    pillar3Title: "पैटर्न पहचान (पैटर्न रिकॉग्निशन)",
    pillar3Desc: "गणितीय संबंधों, आधार-१० की जोड़ियों और बीजगणितीय संरचनाओं की सहज व सहज समझ।",
    pillar3Obs: "जब बच्चा संख्याओं को आसानी से पूरक समूहों में समूहित करता है (जैसे ७ + ८ को ७ + ३ + ५ के रूप में)।",

    pillar4Title: "प्रोसेसिंग स्पीड (गणना की गति)",
    pillar4Desc: "प्रक्रियात्मक गणना की देरी और उंगलियों पर गिनने की आदत को खत्म करना, अंकगणितीय गति को स्वाभाविक रूप से तेज करना।",
    pillar4Obs: "टाइम-ट्रायल अभ्यास द्वारा मापा जाता है जहां प्रतिक्रिया समय प्रति प्रश्न ४ सेकंड से घटकर १ सेकंड से कम हो जाता है।",

    pillar5Title: "एकाग्रता और ध्यान (अटेंशन एंड फोकस)",
    pillar5Desc: "बिना किसी भटकाव या बेचैनी के बहु-चरणीय कार्यों के दौरान निरंतर एकाग्रता बनाए रखना।",
    pillar5Obs: "डिजिटल स्क्रीन थकान के बिना २० मिनट के निर्बाध समस्या-समाधान सत्रों में देखा जाता है।",

    pillar6Title: "संज्ञानात्मक लचीलापन (कॉग्निटिव फ्लेक्सिबिलिटी)",
    pillar6Desc: "पारंपरिक स्कूल गणित विधियों, वैदिक शॉर्टकट और मानसिक दृश्यीकरण के बीच आसानी से स्विच करने की क्षमता।",
    pillar6Obs: "जब बच्चा वैदिक बीजांक (डिजिट-सम) का उपयोग करके स्वतंत्र रूप से मानक भाग विधि की पुष्टि करता है।",

    pillar7Title: "एग्जीक्यूटिव फंक्शन (आत्म-प्रबंधन व नियंत्रण)",
    pillar7Desc: "परीक्षा समय की सीमाओं के दौरान आत्म-निगरानी, व्यवस्थित त्रुटि-जांच और अनुशासित गति।",
    pillar7Obs: "जब बच्चा वर्कशीट जमा करने से पहले अपने हासिल (कैरी-ओवर) की गलती खुद पहचान लेता है।",

