    // Mentor Pillars
    mentorPillarsTitle: "छात्र कल्याण के हमारे 3 स्तंभ",
    mentorPillarsDesc: "हम केवल यांत्रिक अंकों की गणना से परे देखते हैं। नेहा पाटिल और नितिन सर स्थानिक दृश्य स्मृति, सुनने की क्षमता और प्रदर्शन आत्मविश्वास को पोषित करने के लिए शिक्षण मॉड्यूल तैयार करते हैं।",
    mentorPillar1Title: "मैत्रीपूर्ण कक्षा का माहौल",
    mentorPillar1Desc: "हम परीक्षाओं के उच्च-दबाव वाले वातावरण से बचते हैं। नेहा मैम एक दोस्ताना और तनावमुक्त माहौल बनाती हैं ताकि बच्चे गलतियाँ करने और उनसे सीखने में सहज महसूस करें।",
    mentorPillar2Title: "व्यक्तिगत प्रगति (1-ऑन-1)",
    mentorPillar2Desc: "कोई भी दो बच्चे एक ही गति से गणना नहीं करते हैं। यही कारण है कि नेहा मैम और नितिन सर व्यक्तिगत प्रगति पत्रक तैयार करते हैं, जिससे यह सुनिश्चित होता है कि प्रत्येक बच्चा आत्मविश्वास से सीखे।",
    mentorPillar3Title: "प्रमाणित व्यावसायिकता",
    mentorPillar3Desc: "हमारी प्रणालियाँ IIVA (इंडियन इंस्टीट्यूट ऑफ वैदिक मैथ्स एंड एबाकस) के दिशानिर्देशों पर चलती हैं, जो आपके बच्चे को विश्व स्तर पर स्वीकृत गणितीय कौशल देती हैं।",
    mentorConsultTitle: "नेहा मैम के साथ एक फ्री मूल्यांकन का समन्वय करें",
    mentorConsultDesc: "एक डेमो अनुरोध सबमिट करें। हम अपने केंद्र पर एक त्वरित समय तय करेंगे। नेहा मैम व्यक्तिगत रूप से आपके बच्चे की गणना की आदतों का मूल्यांकन करेंगी और उनके लिए एक विशेष सीखने का मार्ग तैयार करेंगी।",
