    progPageMilestoneVeBullet3: "बीजगणित, वर्ग और वर्गमूल के लिए उच्च दृश्य अंतर्ज्ञान",
    progPageAdvisoryBadge: "परामर्श स्लॉट पूछताछ",
    progPageAdvisoryTitle: "अनिश्चित हैं कि कौन सा कोर्स आपके बच्चे की उम्र के अनुकूल है ?",
    progPageAdvisorySubtitle: "एक अनुकूल परामर्श सत्र के लिए हमसे संपर्क करें। नेहा मैम और नितिन सर व्यक्तिगत रूप से आपके बच्चे के सीखने के तरीके, संख्या समझ, तार्किक दृष्टिकोण, ध्यान, अनुशासन और स्कूल बोर्ड की आवश्यकताओं का आकलन करेंगे ताकि आपका सही मार्गदर्शन किया जा सके।",
