    // FAQs Page
    faqBadge: "स्पष्ट उत्तर",
    faqTitle: "अक्सर पूछे जाने वाले प्रश्न",
    faqSubtitle: "आपकी गणितीय शंकाओं का समाधान",
    faqDesc: "एबाकस पाठों, फीस, बैचों या अध्ययन संरचनाओं पर स्पष्टता चाहिए ? हमारे सत्यापित उत्तर पढ़ें।",
    faqCategoryAll: "सभी",
    faqCategoryGeneral: "सामान्य",
    faqCategoryAbacus: "एबाकस मैथ",
    faqCategoryVedic: "वैदिक गणित",
    faqCategorySchool: "स्कूल गणित",
    faq1Question: "एबाकस कक्षाओं में अपने बच्चे का दाखिला कराने की सही उम्र क्या है ?",
    faq1Answer: "एबाकस शुरू करने की आदर्श आयु 4 से 14 वर्ष के बीच है (5 से 9 वर्ष के बीच सर्वोत्तम परिणाम)। इस चरण के दौरान, बच्चे का मस्तिष्क बहुत सक्रिय होता है, जिससे वे संख्याओं को सबकॉन्शियस मेमोरी में तेज़ी से सहेजते हैं।",
    faq2Question: "एबाकस और वैदिक गणित में क्या अंतर है ?",
    faq2Answer: "एबाकस छोटे बच्चों (उम्र 4-14) के लिए स्पर्श आधारित बीड्स के माध्यम से दृश्य स्मृति विकसित करता है। वैदिक गणित बड़े बच्चों (उम्र 10+) के लिए बिना विज़ुअल टूल्स के 10-15 गुना तेज़ी से वर्ग, मूल और बीजगणित हल करने के 16 सूत्रों का उपयोग करता है।",
    faq3Question: "क्या अर्णव एबाकस एकेडमी के शिक्षक प्रमाणित हैं ?",
    faq3Answer: "हाँ, 100% ! अर्णव एबाकस एकेडमी प्रत्यक्ष संकाय नेतृत्व में चलती है। संस्थापक नेहा पाटिल एक पूर्ण IIVA प्रमाणित पेशेवर हैं।",
    faq4Question: "प्रत्येक सत्र की अवधि क्या है, और क्लास का समय क्या है ?",
    faq4Answer: "हम व्यस्त दिनचर्या के अनुकूल सप्ताह के सातों दिन खुले हैं, और कार्यदिवसों एवं सप्ताहांतों दोनों में लचीले सत्र प्रदान करते हैं।",
    faq5Question: "क्या विजुअल एबाकस सीखने से मेरे बच्चे के स्कूल गणित के सिलेबस में भ्रम होगा ?",
    faq5Answer: "नहीं, इसके विपरीत ! एबाकस प्रशिक्षण स्कूल के सिलेबस की गणना में बाधा नहीं डालता। बल्कि, यह गणना की गति को कई गुना बढ़ा देता है जिससे परीक्षा में बेहतर ग्रेड मिलते हैं।",

