    campBenefitsTitle: "तत्काल शैक्षणिक मील के पत्थर सुरक्षित करने के लिए डिज़ाइन किया गया",
    campBenefitsDesc: "डबल डिजिट कैलकुलेशन, फोटोग्राफिक मेमोरी संरचना और पूर्ण मानसिक शांति प्राप्त करें। नेहा पाटिल (IIVA प्रमाणित) हमारे वाकड केंद्र का संचालन करती हैं, जो प्रत्येक बच्चे के आत्मविश्वास के विकास पर ध्यान देती हैं।",
