    campFooterContact: "संपर्क फोन: +91 90219 24968 | संस्थापक नेहा पाटिल (IIVA प्रमाणित)",

    faq6Question: "क्या आप कक्षा 1-10 की स्कूली परीक्षाओं के लिए व्यक्तिगत कोचिंग प्रदान करते हैं ?",
    faq6Answer: "हाँ। हमारा स्कूल गणित पाठ्यक्रम शैक्षणिक आत्मविश्वास और परीक्षा प्रदर्शन को बढ़ावा देने के लिए डिज़ाइन किया गया है। हम प्रत्येक बच्चे की सक्रिय पाठ्यपुस्तक श्रृंखला (NCERT, CBSE, स्थानीय बोर्ड) का विश्लेषण करते हैं, व्यक्तिगत गृहकार्य को हल करते हैं, और एक शांत वातावरण में व्यापक नमूना प्रश्न पत्रों का अभ्यास कराते हैं।",
    faq7Question: "क्या आप ऑनलाइन सेशन प्रदान करते हैं या केवल ऑफलाइन बैच ?",
    faq7Answer: "हमारी प्राथमिक विशेषता हमारे बंगले केंद्र पर प्रीमियम हैंड-गाइडेड ऑफलाइन बैच हैं, जो क्रिएटिव कैमियो के सामने है, जिससे बच्चे का ध्यान, व्यक्तिगत ट्यूटर सुरक्षा और विजुअल बीड जुड़ाव सुनिश्चित होता है। विशेष मामलों या उन्नत वैदिक गणित खंडों के लिए, माता-पिता के अनुरोध पर ऑनलाइन बैच भी संचालित किए जाते हैं।",
    faq8Question: "आपके कोर्स राष्ट्रीय शिक्षा नीति (NEP) २०२० के साथ कैसे संरेखित हैं ?",
    faq8Answer: "अर्णव एबाकस एकेडमी पूरी तरह से NEP २०२० के दिशा-निर्देशों के अनुरूप है। हमारा एबाकस पाठ्यक्रम व्यावहारिक शिक्षण (experiential learning) के माध्यम से शुरुआती उम्र (३–८ वर्ष) के लिए बुनियादी साक्षरता और संख्याज्ञान (FLN) का समर्थन करता है। इसके अतिरिक्त, हमारी वैदिक गणित कक्षाएं भारतीय ज्ञान प्रणाली (IKS) को बढ़ावा देती हैं, जिससे बच्चों को गणितीय सोच विकसित करने और भय मुक्त होने में मदद मिलती है।",
    faqSyllabusConflictQuestion: "क्या बाएं-से-दाएं एबाकस विधि स्कूल की दाएं-से-बाएं गणना के साथ संघर्ष करती है?",
    faqSyllabusConflictAnswer: "नहीं। जिस तरह द्विभाषी बच्चे बिना किसी भ्रम के दो भाषाएं आसानी से बोल लेते हैं, उसी तरह छात्र स्कूल की कॉलम जोड़ (इकाई पहले) और मानसिक एबाकस विज़ुअलाइज़ेशन (बाएं-से-दाएं) को आसानी से विभाजित कर लेते हैं। यह वास्तव में उनके उत्तरों को क्रॉस-वेरिफाई करने में मदद करता है।",
    faqStepMarksQuestion: "यदि मेरा बच्चा मानसिक रूप से गणना करता है, तो वह स्कूल की गणित परीक्षाओं में चरण-दर-चरण प्रमाण कैसे लिखेगा?",
    faqStepMarksAnswer: "अर्णव एबाकस एकेडमी बच्चों को उत्तर तेजी से खोजने के लिए मानसिक गणना का उपयोग करना सिखाती है, जबकि उनके नियमित स्कूल की कक्षाएं उन्हें स्टेप्स लिखना सिखाती हैं। वे अपने काम की जांच करने में गति प्राप्त करते हैं, जिससे परीक्षाओं के दौरान समय बचता है।",
    faqWordProblemsQuestion: "क्या एबाकस केवल गणना की गति में मदद करता है, या यह वर्ड प्रॉब्लम और तार्किक सोच में भी सुधार करता है?",
    faqWordProblemsAnswer: "एबाकस ग्रिड पर संख्याओं की कल्पना करने से मस्तिष्क का पार्श्व पालि (parietal lobe) सक्रिय होता है, जो स्थानिक तर्क (spatial reasoning) के लिए जिम्मेदार है। यह ज्यामितीय संबंधों, बीजगणितीय तर्क और संरचित वर्ड प्रॉब्लम को बेहतर ढंग से हल करने में सीधे मदद करता है।",
