    teacherBioP1: "नेहा पाटील या एमसीए आणि सोरोबन ॲबॅकस व वैदिक गणितातील आयआयव्हीए दिल्ली-प्रमाणित प्रशिक्षक आहेत. बाल-केंद्रित शिक्षण पद्धतीद्वारे, त्या पाठांतराऐवजी फोटोग्राफिक दृश्यीकरण, संख्यांची चपळता आणि तार्किक स्वावलंबनावर भर देतात.",
