    progVedicQ1: "वैदिक पद्धती वापरल्यास शाळेतील शिक्षक गुण कापतील का?",
    progVedicA1: "नाही. शालेय परीक्षेत (CBSE/ICSE) विद्यार्थी सर्व पायऱ्या पद्धतशीरपणे लिहून पूर्ण गुण मिळवतात. ते केवळ आकडेमोड वेगाने करण्यासाठी आणि उत्तर तपासण्यासाठी वैदिक पद्धतीचा वापर करतात.",
    progVedicQ2: "ॲबॅकस आणि वैदिक गणितात काय फरक आहे?",
    progVedicA2Part1: "ॲबॅकस लहान मुलांसाठी (वय ४-१४) प्रत्यक्ष मण्यांचा वापर करून मेंदूचा विकास आणि दृश्यीकरण शिकवतो. वैदिक गणित १० वर्षांवरील विद्यार्थ्यांसाठी मानसिक सूत्रांचा वापर करून आकडेमोड व बीजगणित सोडवण्यास मदत करतो. अधिक माहितीसाठी वाचा: ",
    progVedicA2Link: "ॲबॅकस विरुद्ध वैदिक गणित सविस्तर माहिती",
    progVedicA2Part2: ".",
    progVedicQ3: "वैदिक गणित शिकण्यासाठी आधी ॲबॅकस शिकणे गरजेचे आहे का?",
    progVedicA3: "अजिबात नाही. वैदिक गणित ही एक स्वतंत्र पद्धत आहे. ५ वी किंवा त्यापुढील कोणताही विद्यार्थी ज्याला मूलभूत पाढे आणि अंकगणित समजते, तो सहज वैदिक गणित शिकू शकतो.",
