    progVedicTrustDesc: "अर्णव ॲबॅकस अकॅडमीमध्ये प्रमाणित शिक्षकांद्वारे प्रत्यक्ष आणि ऑनलाइन लहान बॅचेस चालवल्या जातात. आमचे केंद्र वाकड, पुणे येथे विस्डम वर्ल्ड स्कूलच्या मागे, पार्क स्ट्रीट जवळ आहे.",
