    faqCategorySchool: "शालेय गणित",
    faq1Question: "ॲबॅकस वर्गासाठी प्रवेश घेण्याचे योग्य वय कोणते आहे ?",
    faq1Answer: "ॲबॅकस शिकण्यासाठी योग्य वय ४ ते १४ वर्षे आहे (५ ते ९ वर्षांच्या दरम्यान सर्वोत्तम परिणाम मिळतात). या वयात मेंदूचा विकास वेगाने होत असतो.",
    faq2Question: "ॲबॅकस आणि वैदिक गणित या दोन पद्धतींमध्ये काय फरक आहे ?",
    faq2Answer: "ॲबॅकस मण्यांच्या साहाय्याने लहान मुलांच्या (वय ४-१४) उजव्या मेंदूचा विकास करतो. वैदिक गणित मोठ्या मुलांसाठी (वय १०+) तोंडी आकडेमोड करण्याचे १६ सूत्रे शिकवते.",
    faq3Question: "अर्णव ॲबॅकस अकॅडमीचे शिक्षक प्रमाणित आहेत का ?",
    faq3Answer: "होय, १००% अधिकृत ! अर्णव ॲबॅकस अकॅडमी नेहा पाटील यांच्या मार्गदर्शनाखाली चालते. नेहा मॅडम स्वतः पूर्णपणे IIVA प्रमाणित मार्गदर्शिका आहेत.",
    faq4Question: "क्लासचा वेळ किती असतो आणि आठवड्यातून किती दिवस वर्ग असतात ?",
    faq4Answer: "आम्ही पालकांच्या आणि विद्यार्थ्यांच्या सोयीनुसार आठवड्याचे सातही दिवस वर्ग घेतो.",
    faq5Question: "ॲबॅकस शिकल्याने मुलांच्या शाळेतील अभ्यासक्रमात काही गोंधळ होईल का ?",
    faq5Answer: "नाही, मुळीच नाही ! ॲबॅकसमुळे शाळेतील सीबीएसई, आयसीएसई किंवा राज्य बोर्डाच्या पद्धतींमध्ये कोणताही अडथळा येत नाही. उलट, वेगामध्ये खूप सुधारणा होते.",

