    c4Solution: "ऐकणे आणि मणी हलविणे या दोन्ही गोष्टी एकत्र केल्याने मुलाची एकाग्रता वाढते आणि लक्ष विचलित होणे बंद होते.",
    c4Science: "डिक्टेशनच्या वेगाने आकडेमोड करताना मेंदूला बाहेरील आवाज ब्लॉक करावे लागतात, ज्यामुळे मेंदूतील लक्ष केंद्रित करणारी यंत्रणा बळकट होते.",
    c4Academy: "आमचे वर्ग १० मिनिटांच्या लहान आणि ऊर्जावान सत्रांमध्ये विभागलेले असतात. शिक्षक विविध रंजक पातळ्यांद्वारे मुलांना व्यस्त ठेवतात.",
    concern5Title: "संख्यात्मक तर्काचा (लॉजिक) अभाव",
