    c5Sub1: "शाब्दिक उदाहरणात एकही शब्द बदलल्यास कबीर गोंधळून जातो.",
    c5Sub2: "तो गणिताला तार्किक समजून घेण्याऐवजी फक्त पाठांतर करण्याचे नियम समजतो.",
    c5Sub3: "पाठांतर केलेले विसरू शकते कारण सूत्रे अमूर्त असतात. ॲबॅकस संख्यांना भौतिक स्वरूपात दाखवतो.",
    c5Sub4: "जेव्हा मुले पाहतात की मणी म्हणजे जागा आणि प्रमाण आहे, तेव्हा त्यांना मूळ लॉजिक समजते.",
    c5Solution: "संख्यांना मण्यांच्या आणि जागेच्या स्वरूपात दाखविल्याने पाठांतराशिवाय मुलांमध्ये खरी तार्किक विचारसरणी विकसित होते.",
    c5Science: "ॲबॅकस मेंदूमध्ये संख्यांच्या प्रमाणाचा एक नकाशा तयार करतो. हा मेंदूचा भाग तार्किक संख्या ज्ञान आणि आकडेमोड हाताळतो.",
    c5Academy: "आम्ही आमच्या सिनर्जी मॅट्रिक्सद्वारे संख्यांचे लॉजिक शिकवतो. आम्ही शालेय अभ्यासक्रमाला ॲबॅकससोबत जोडतो जेणेकरून मुलांना प्रत्येक नियमाचे मूळ कारण समजेल.",

