    campTrialBadge: "मोफत ट्रायल कॅम्पेन",
    campBenefitsBadge: "पालकांसाठी विशेष माहिती व फायदे",
    campBenefitsTitle: "मुलांच्या शैक्षणिक विकासासाठी रचलेला विशेष उपक्रम",
    campBenefitsDesc: "दुहेरी अंकांची जलद आकडेमोड, फोटोग्राफिक मेमरीचा विकास आणि पालकांसाठी पूर्ण समाधान मिळवा. नेहा पाटील (IIVA प्रमाणित) वाकड येथील आमच्या सेंटरमध्ये प्रत्येक विद्यार्थ्याच्या प्रगतीकडे वैयक्तिक लक्ष देतात.",
