    faq6Question: "तुम्ही इयत्ता १ ली ते १० वी च्या विद्यार्थ्यांसाठी शालेय परीक्षेची विशेष तयारी करून घेता का ?",
    faq6Answer: "होय. आमचा शालेय गणिताचा अभ्यासक्रम विद्यार्थ्यांचा आत्मविश्वास आणि परीक्षेतील गुण वाढवण्यासाठी डिझाइन केला आहे. आम्ही विद्यार्थ्यांच्या शाळेतील बोर्डानुसार (NCERT, CBSE, राज्य बोर्ड) पुस्तकांचा अभ्यास घेऊन, त्यांच्याकडून सरावपत्रिका सोडून घेतो.",
    faq7Question: "तुम्ही ऑनलाइन क्लास घेता की फक्त ऑफलाइन बॅचेस असतात ?",
    faq7Answer: "आम्ही प्रामुख्याने क्रिएटिव्ह कॅमिओच्या समोर असलेल्या आमच्या बंगल्यामध्ये ऑफलाइन बॅचेसद्वारे शिकवण्यावर भर देतो. यामुळे मुलांचे लक्ष एकाग्र राहते आणि वैयक्तिक प्रगती होते. विशेष प्रकरणांमध्ये किंवा वैदिक गणिताच्या प्रगत भागासाठी पालकांच्या विनंतीनुसार ऑनलाइन बॅचेस देखील घेतल्या जातात.",
    faq8Question: "तुमचे कोर्सेस राष्ट्रीय शैक्षणिक धोरण (NEP) २०२० शी कसे सुसंगत आहेत ?",
    faq8Answer: "अर्णव ॲबॅकस अकॅडमी पूर्णपणे NEP २०२० च्या मार्गदर्शक तत्त्वांशी सुसंगत आहे. आमचा ॲबॅकस अभ्यासक्रम प्रत्यक्ष कृतीद्वारे शिक्षणावर (experiential learning) भर देऊन लहान मुलांसाठी (वय ३–८ वर्षे) पायाभूत साक्षरता आणि संख्याज्ञान (FLN) भक्कम करतो. तसेच, आमचे वैदिक गणिताचे वर्ग भारतीय ज्ञान प्रणालीला (IKS) प्रोत्साहन देतात, ज्यामुळे विद्यार्थ्यांची गणितीय भीती दूर होऊन तार्किक विचारसरणी आणि मानसिक गती वाढते.",
    faqSyllabusConflictQuestion: "डावीकडून उजवीकडे मोजण्याची ॲबॅकस पद्धत शाळेतील उजवीकडून डावीकडे मोजण्याच्या पद्धतीशी विसंगत ठरते का?",
    faqSyllabusConflictAnswer: "नाही. ज्याप्रमाणे द्विभाषिक मुले कोणत्याही गोंधळाशिवाय दोन्ही भाषा अस्खलितपणे बोलू शकतात, त्याचप्रमाणे विद्यार्थी शाळेतील पद्धत (आधी एकक स्थान) आणि ॲबॅकस पद्धत (डावीकडून उजवीकडे) या दोन्ही पद्धती सहजपणे हाताळतात. उलट यामुळे उत्तराची अचूकता पडताळणे सोपे जाते.",
    faqStepMarksQuestion: "माझ्या मुलाने तोंडी आकडेमोड केल्यास त्याला शाळेत पायऱ्यांनुसार (Step-by-step) लिहिण्याचे गुण मिळतील का?",
    faqStepMarksAnswer: "अर्णव ॲबॅकस अकॅडमी विद्यार्थ्यांना जलद गतीने अचूक उत्तरे शोधण्यासाठी तोंडी आकडेमोड शिकवते, तर नियमित शालेय वर्ग त्यांना पायऱ्या लिहून स्पष्टीकरण देणे शिकवतात. यामुळे मुले कमी वेळेत आपले उत्तर तपासून पाहू शकतात, ज्यामुळे परीक्षेतील वेळ वाचतो.",
    faqWordProblemsQuestion: "ॲबॅकसमुळे फक्त गणितीय वेग वाढतो की तोंडी शाब्दिक प्रश्न आणि तार्किक विचारसरणीतही सुधारणा होते?",
    faqWordProblemsAnswer: "ॲबॅकस ग्रिडवर संख्यांचे दृश्य रूप पाहिल्याने मेंदूचा पॅरिएटल लोब (parietal lobe) सक्रिय होतो, जो स्थानिक विचारसरणीसाठी (spatial reasoning) महत्त्वाचा असतो. यामुळे भूमितीय संबंध, बीजगणितीय तर्क आणि कठीण शाब्दिक प्रश्न सहज समजून सोडवण्यास मदत होते.",
